async ({ git: { log, tag, push, status } }) => {
  const l = await log(["--oneline", "-3"]);
  const st = await status(["--short", "--branch"]);
  if (!l.stdout.split("\n")[0].includes("chore(release): v0.39.2")) return { l, st, abort: true };
  await tag(["-a", "v0.39.2", "-m", "pit v0.39.2"], { raise: true } as any);
  const p = await push(["origin", "v0.39.2"], { raise: true } as any);
  return { l: l.stdout, st: st.stdout, p: p.stderr };
}
